"""Integrate Veilradio Float Mode into the app page after previous build patches."""
from pathlib import Path
import sys
p=Path(sys.argv[1]) if len(sys.argv)>1 else Path('app/src/main/assets/veilradio.html')
s=p.read_text(encoding='utf-8')
a=s.find("const app=document.getElementById('app');")
if a<0: raise RuntimeError('Veilradio app controller missing')
b=s.find('})();</script>',a)
if b<0: raise RuntimeError('Veilradio app controller end missing')
if 'VEILRADIO / FLOAT MODE INTEGRATION' in s: raise RuntimeError('Already patched')
patch="/* VEILRADIO / FLOAT MODE INTEGRATION - real library, OpenAI/Deezer and saved tracks */\nlet floatWindow=null,floatFrame=null;\nconst floatTab=document.createElement('button');\nfloatTab.className='navBtn';floatTab.type='button';floatTab.dataset.page='float';\nfloatTab.setAttribute('aria-label','Float discovery mode');\nfloatTab.innerHTML='<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 3c5.4 0 9 3.6 9 9s-3.6 9-9 9-9-3.6-9-9 3.6-9 9-9z\"/><path d=\"M7 13c3-5 7-5 10-1\"/></svg><small>Float</small>';\nconst playerTab=qs('.navBtn[data-page=\"player\"]',app);\nif(playerTab)playerTab.parentElement.insertBefore(floatTab,playerTab);\nelse qs('.navGlass',app)?.appendChild(floatTab);\nfunction floatClose(){\n if(floatWindow){floatWindow.remove();floatWindow=null;floatFrame=null;}\n app.dataset.page=state.page;\n qa('.navBtn[data-page]',app).forEach(btn=>{let on=btn.dataset.page===state.page;btn.classList.toggle('active',on);btn.setAttribute('aria-current',on?'page':'false')});\n}\nfunction floatOpen(){\n if(floatWindow)return;\n try{pause();localAudio.pause();previewAudio.pause()}catch(e){}\n floatWindow=document.createElement('div');floatWindow.id='veilFloatWindow';\n floatWindow.style.cssText='position:fixed;inset:0;width:100vw;height:100dvh;z-index:2147483000;background:#f5f2f4;overflow:hidden';\n floatFrame=document.createElement('iframe');floatFrame.id='veilFloatFrame';floatFrame.title='Veilradio Float Mode';\n floatFrame.setAttribute('allow','autoplay');floatFrame.setAttribute('referrerpolicy','same-origin');\n floatFrame.style.cssText='border:0;display:block;width:100%;height:100%;background:#f6f3f4';\n floatFrame.src='float.html?embedded=1';\n floatWindow.appendChild(floatFrame);document.body.appendChild(floatWindow);\n app.dataset.page='float';\n qa('.navBtn[data-page]',app).forEach(btn=>{const on=btn===floatTab;btn.classList.toggle('active',on);btn.setAttribute('aria-current',on?'page':'false')});\n}\nfloatTab.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();floatOpen()});\n// Existing app pages continue using the original navigation controller.\nqa('.navBtn[data-page]',app).filter(x=>x!==floatTab).forEach(x=>x.addEventListener('click',()=>{if(floatWindow)floatClose()}));\nfunction floatIdentity(t){return String(t?.deezerId||t?.id||t?.num||'')+'|'+String(t?.artist||'').toLowerCase()+'|'+String(t?.title||'').toLowerCase()}\nfunction floatSeeds(){\n const all=[...(state.sessionQueue||[]).slice(-30).reverse(),...(state.extraDiscoveries||[]).slice(-30).reverse(),...tracks];\n const seen=new Set(),out=[];\n for(const t of all){if(!t||!t.artist||!t.title)continue;let key=normalizedIdentity(t.artist)+':'+normalizedIdentity(t.title);\n  if(seen.has(key))continue;seen.add(key);\n  const id=String(t.deezerId||'').match(/^\\d{1,16}$/)?.[0]||'';\n  out.push({id:id?'dz'+id:String(t.num||'seed'+out.length),deezerId:id,title:t.title,artist:t.artist,mood:['veil','rose','ice'][out.length%3],url:'',source:'catalogue'});\n  if(out.length>=7)break;\n }\n return out;\n}\nasync function floatPreview(data){\n const id=String(data.deezerId||'').replace(/^dz/,'');\n let t=null;\n if(/^\\d{1,16}$/.test(id)){\n  try{t=(await liveRequest('/api/deezer/track?id='+encodeURIComponent(id))).track}catch(e){}\n }\n if(!t){const items=await deezerSearch(data.artist+' '+data.title);\n  const a=normalizedIdentity(data.artist),z=normalizedIdentity(data.title);\n  t=items.find(x=>normalizedIdentity(x.artist)===a&&normalizedIdentity(x.title)===z&&x.preview)||\n    items.find(x=>normalizedIdentity(x.artist)===a&&x.preview)||null;\n }\n return t?.preview||'';\n}\nfunction floatBookmark(t,on){\n if(!t?.artist||!t?.title)throw Error('Invalid saved recording');\n state.extraDiscoveries=state.extraDiscoveries||[];\n const key=normalizedIdentity(t.artist)+':'+normalizedIdentity(t.title);\n let found=[...tracks,...state.extraDiscoveries].find(z=>normalizedIdentity(z.artist)+':'+normalizedIdentity(z.title)===key);\n state.floatArchiveKeys=state.floatArchiveKeys||[];\n if(on){\n  if(!found){let num='float_'+Date.now()+'_'+Math.random().toString(36).slice(2,7);\n   found={num,title:t.title,artist:t.artist,genre:'FLOAT / DEEZER',art:Math.floor(Math.random()*7),deezerId:t.deezerId||String(t.id||'').replace(/^dz/,'')};\n   state.extraDiscoveries.push(found);\n  }\n  reactionMap[found.num]='love';\n  if(!state.floatArchiveKeys.includes(key))state.floatArchiveKeys.push(key);\n  if(t.url&&t.url.includes('deezer.com/track/'))state.linkMap[found.num]=t.url;\n  rememberClassification(found,'love');\n }else if(state.floatArchiveKeys.includes(key)&&found){\n  delete reactionMap[found.num];forgetClassification(found);\n  state.floatArchiveKeys=state.floatArchiveKeys.filter(k=>k!==key);\n }\n save();saveState();\n return {saved:on};\n}\nwindow.addEventListener('message',async event=>{\n if(!floatFrame||event.source!==floatFrame.contentWindow)return;\n const request=event.data||{};\n if(request.type==='veil-float-close'){floatClose();return}\n if(request.type==='veil-float-ready'){\n  event.source.postMessage({type:'veil-float-init',tracks:floatSeeds()},'*');return;\n }\n if(request.type!=='veil-float-request'||!/^float\\d{1,10}$/.test(String(request.requestId||'')))return;\n let result={},error='';\n try{\n  if(request.action==='related'){\n   const seed=request.seed||{},ex=discoveryExclusions();\n   const ids=new Set(ex.ids||[]),names=new Set(ex.names||[]);\n   for(const s of (request.exclude||[]).slice(0,40)){\n    const id=String(s.deezerId||s.id||'').replace(/^dz/,'');if(/^\\d{1,16}$/.test(id))ids.add(id);\n    names.add(normalizedIdentity(s.artist)+':'+normalizedIdentity(s.title));\n   }\n   const depth=Number.isFinite(state.discoveryDepth)?state.discoveryDepth:78;\n   const instruction=depth>=75?'Find deep underground and niche adjacent artists, not popular mainstream hits.':\n     depth>=40?'Find distinctive leftfield artists alongside deeper cuts.':'Discover related artists with approachable songs.';\n   const out=await livePost('/api/discover',{mode:'seed',seed:seed.artist+' - '+seed.title,\n    signal:instruction,depth,recent:liveRecent(),exclude:{ids:[...ids].slice(-450),names:[...names].slice(-450)}});\n   const rows=(out.tracks||[]).filter(t=>!alreadyCategorized(t)&&!names.has(normalizedIdentity(t.artist)+':'+normalizedIdentity(t.title)))\n    .map((t,i)=>({id:'dz'+t.id,deezerId:String(t.id),artist:t.artist,title:t.title,mood:['veil','rose','ice'][i%3],source:'deezer',url:'',preview:t.preview||''}));\n   result={tracks:rows};\n  }else if(request.action==='preview'){result={url:await floatPreview(request.track||{})};}\n  else if(request.action==='bookmark'){result=floatBookmark(request.track,!!request.saved);}\n  else throw Error('Unknown Float operation');\n }catch(err){error=String(err?.message||err).slice(0,180)}\n try{event.source.postMessage({type:'veil-float-result',requestId:request.requestId,data:result,error},'*')}catch(e){}\n});\n\n"
s=s[:b]+patch+'\n'+s[b:]
p.write_text(s,encoding='utf-8')
print('Float Mode integrated:',p)
